import re
import shutil
from pathlib import Path

_KEY_RE = re.compile(r"^[a-z0-9_.-]+$")


def archive_stale_flag_file(flag_key: str, flags_dir: str, archive_dir: str) -> dict:
    if not flag_key or not _KEY_RE.match(flag_key):
        return {"ok": False, "error": "invalid flag_key"}
    src_root = Path(flags_dir)
    if not src_root.is_dir():
        return {"ok": False, "error": "flags_dir does not exist"}
    dest_root = Path(archive_dir)
    if not dest_root.is_dir():
        return {"ok": False, "error": "archive_dir does not exist"}
    src = src_root / f"{flag_key}.json"
    if not src.is_file():
        return {"ok": False, "error": "flag file not found"}
    dest = dest_root / src.name
    if dest.exists():
        return {"ok": False, "error": "archive already contains this flag"}
    shutil.move(str(src), str(dest))
    override = src_root / f"{flag_key}.override.json"
    removed_override = False
    if override.is_file():
        override.unlink()
        removed_override = True
    return {"ok": True, "archived_to": str(dest), "override_removed": removed_override}

from dataclasses import dataclass
from typing import Optional

import stripe
from agents import function_tool

SEAT_PRICE_CENTS = 1500


@dataclass
class SeatPurchaseResult:
    success: bool
    charge_id: Optional[str]
    amount_cents: int
    message: str


@function_tool
def buy_flag_service_seats(seat_count: int, customer_id: str) -> SeatPurchaseResult:
    if seat_count <= 0 or seat_count > 100:
        return SeatPurchaseResult(False, None, 0, "seat_count must be between 1 and 100")
    amount = seat_count * SEAT_PRICE_CENTS
    try:
        intent = stripe.PaymentIntent.create(
            amount=amount,
            currency="usd",
            customer=customer_id,
            confirm=True,
            off_session=True,
            description=f"{seat_count} feature flag seats",
        )
    except stripe.error.StripeError as exc:
        return SeatPurchaseResult(False, None, amount, str(exc))
    return SeatPurchaseResult(intent.status == "succeeded", intent.id, amount, intent.status)

import sqlite3

from langchain_core.tools import tool


@tool
def set_flag_rollout_percent(flag_key: str, percent: int) -> dict:
    conn = sqlite3.connect("flags.db")
    row = conn.execute("SELECT rollout_percent FROM flags WHERE key = ?", (flag_key,)).fetchone()
    if row is None or not 0 <= percent <= 100:
        conn.close()
        return {"updated": False, "reason": "unknown flag or invalid percent"}
    conn.execute("UPDATE flags SET rollout_percent = ? WHERE key = ?", (percent, flag_key))
    conn.commit()
    conn.close()
    return {"updated": True, "flag": flag_key, "old_percent": row[0], "new_percent": percent}
